"""Family U1: cyclic groups of order 11 generated by a single unipotent element (root elements and random elements of U)."""
import sys, os, random, json, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import lie
from lie import L, q, POS_ROOTS
from frob import run_group
t = float(sys.argv[1]) if len(sys.argv) > 1 else 15
random.seed(7)
tests = []
for beta in POS_ROOTS:
    tests.append(('R_%d%d%d' % (beta[0]+1, beta[1]+1, beta[2]+1), [lie.root_elt(beta, 1)]))
for k in range(4):
    M = L.mat_id(7)
    for beta in POS_ROOTS:
        M = L.mat_mul(M, lie.root_elt(beta, random.randrange(1, q)), q)
    tests.append(('RU%d' % k, [M]))
for name, mats in tests:
    best, res, info = run_group('U1_' + name, mats, t=t, seed=1)
    print(name, 'best', best, '|', (res or '')[:120], flush=True)
    for i in info: print('    ', i, flush=True)
